-- Create table for NHTSA National Statistics
CREATE TABLE NHTSA_NATIONAL_STATS (
    stat_id INT PRIMARY KEY AUTO_INCREMENT,
    year INT NOT NULL,
    fatal_crashes INT,
    total_fatalities INT,
    drivers_killed INT,
    passengers_killed INT,
    unknown_occupants INT,
    vehicle_occupants_total INT,
    motorcyclists_killed INT,
    pedestrians_killed INT,
    pedalcyclists_killed INT,
    other_nonmotorists_killed INT,
    nonmotorists_total INT,
    vehicle_miles_traveled DECIMAL(10, 2),
    resident_population INT,
    registered_vehicles INT,
    licensed_drivers INT,
    fatality_rate_per_100m_vmt DECIMAL(5, 2),
    fatality_rate_per_100k_pop DECIMAL(5, 2),
    fatality_rate_per_100k_vehicles DECIMAL(5, 2),
    fatality_rate_per_100k_drivers DECIMAL(5, 2),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY unique_year (year)
);

